'use client';import { useState, useEffect, useRef, FormEvent } from 'react';import Image from 'next/image';import Link from 'next/link';import Navbar from '@/components/Navbar';import Footer from '@/components/Footer';import ClientProviders from '@/components/ClientProviders';import FeaturedIngredients from '@/components/FeaturedIngredients';import SecondaryOutlineBtn from '@/components/SecondaryOutlineBtn';import { TrustMarkerItem } from '@/components/TrustMarkers';import { TRUST_MARKERS } from '@/components/TrustMarkersData';import { useCart, parsePrice } from '@/lib/cart';import { useWishlist } from '@/lib/wishlist';import {  getHomeContent,  getGlobalSettings,  getIngredientsContent,} from '@/services/api';import type { WooProduct } from '@/services/types';// Homepage product rails read the catalogue client-side via /api/products.// Product SEO lives on /products/<slug>, which is server-rendered, so fetching// these below-the-fold rails on the client costs nothing and keeps this page// static â€” which matters on a 2-core shared host.import { useProducts } from '@/hooks/useProducts';const {  hero,  heroImages,  bestSellers,  brandPhilosophy,  pillars,  founderNote,  ourRange,} = getHomeContent();const { contact } = getGlobalSettings();const { stories } = getIngredientsContent();import { PawPrint } from 'lucide-react';// â”€â”€â”€ Scroll-reveal hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€function useReveal(threshold = 0.3) {  const ref = useRef<HTMLElement>(null);  const [visible, setVisible] = useState(false);  useEffect(() => {    const el = ref.current;    if (!el) return;    const obs = new IntersectionObserver(      ([entry]) => { setVisible(entry.isIntersecting); },      { threshold }    );    obs.observe(el);    return () => obs.disconnect();  }, [threshold]);  return { ref, visible };}// â”€â”€â”€ Inline SVG icons â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€function BtnArrow({ className = '' }: { className?: string }) {  return (    <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" aria-hidden="true" className={`btn-arrow flex-shrink-0 ${className}`}>      <line x1="1" y1="7" x2="13" y2="7" />      <polyline points="8,2 13,7 8,12" />    </svg>  );}// Dog outline â€” for species badgefunction DogIcon() {  return (    <svg width="12" height="12" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ display: 'inline', verticalAlign: 'middle', flexShrink: 0 }}>      <path d="M14 2l2 2v3h2l1 2-2 1v4a2 2 0 01-2 2H5a2 2 0 01-2-2V9L1 8l1-2h2V4l2-2h1l1 2h4l1-2h1Z" />      <circle cx="7.5" cy="10.5" r="0.7" fill="currentColor" stroke="none" />      <circle cx="12.5" cy="10.5" r="0.7" fill="currentColor" stroke="none" />    </svg>  );}// Cat outline â€” for species badgefunction CatIcon() {  return (    <svg width="12" height="12" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ display: 'inline', verticalAlign: 'middle', flexShrink: 0 }}>      <path d="M4 2L2 6v6a6 6 0 0012 0V6L12 2l-2 3h-4L4 2Z" />      <circle cx="7.5" cy="10" r="0.7" fill="currentColor" stroke="none" />      <circle cx="12.5" cy="10" r="0.7" fill="currentColor" stroke="none" />      <path d="M8.5 12.5c.4.5 2.6.5 3 0" />    </svg>  );}// Ghost bag icon for quick-add overlayfunction BagIconOutline() {  return (    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">      <path d="M2 4h12l-1.5 9H3.5L2 4Z" />      <path d="M5.5 4C5.5 2.067 6.567 1 8 1s2.5 1.067 2.5 3" />    </svg>  );}// â”€â”€â”€ Species badge â€” matches Best Seller pill style (ivory bg, charcoal text) â”€â”€function SpeciesBadge({ species, className = '' }: { species?: 'dog' | 'cat' | 'both'; className?: string }) {  if (!species) return null;  return (    <span      className={`inline-flex flex-row items-center gap-1 px-2 py-0.5 bg-[#F8F5F1]/85 text-[#3B3A38] text-[0.6875rem] font-normal tracking-[0.14em] uppercase leading-none ${className}`}      style={{ fontFamily: 'var(--font-inter)', whiteSpace: 'nowrap' }}    >      {(species === 'dog' || species === 'both') && <DogIcon />}      {(species === 'cat' || species === 'both') && <CatIcon />}      <span style={{ lineHeight: 1 }}>        {species === 'dog' && 'Dog'}        {species === 'cat' && 'Cat'}        {species === 'both' && 'Dog & Cat'}      </span>    </span>  );}// â”€â”€â”€ Product card â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€// Hierarchy: image â†’ name â†’ variant/volume â†’ price â†’ add to cart// Hover: card scale+tilt, image zoom 3-4%, border â†’ sagetype ProductItem = WooProduct;function ProductCard({ product }: { product: ProductItem }) {  const [quickAdded, setQuickAdded] = useState(false);  const { addItem, openDrawer } = useCart();  const { toggleWishlist, isInWishlist } = useWishlist();  // eslint-disable-next-line @typescript-eslint/no-explicit-any  const prod = product as any;  // Multi-variant: use first variant for quick-add price/image  const hasVariants = 'variants' in prod && Array.isArray(prod.variants) && prod.variants.length > 0;  const firstVariant = hasVariants ? prod.variants[0] : null;  const displayPrice = firstVariant ? firstVariant.price : product.price;  const displayImage = firstVariant?.image?.src ? firstVariant.image : product.image;  // Single-variant label shown on card  const singleVariantLabel: string | undefined = !hasVariants && prod.variantLabel ? prod.variantLabel : undefined;  const volume: string | undefined = prod.volume;  const isWishlisted = isInWishlist(product.id);  function handleQuickAdd(e: React.MouseEvent) {    e.preventDefault();    e.stopPropagation();    if (quickAdded) return;    addItem({      id: product.id,      name: product.name,      price: displayPrice,      priceNum: parsePrice(displayPrice),      image: displayImage?.src ?? '',      imageAlt: displayImage?.alt ?? product.name,      variantId: firstVariant?.id,      variantLabel: firstVariant?.label ?? singleVariantLabel,    });    setQuickAdded(true);    setTimeout(() => {      setQuickAdded(false);      openDrawer();    }, 800);  }  return (    <Link      href={`/products/${product.id}`}      className="group flex flex-col h-full bg-[#F8F5F1] overflow-hidden border border-[#D8CFC4] hover:border-[#8D9A83] focus:outline-none focus-visible:ring-1 focus-visible:ring-[#8D9A83] transition-[transform,border-color] duration-[800ms] ease-out hover:[transform:scale(1.015)_rotate(0.4deg)]"      style={{ WebkitTapHighlightColor: 'transparent' }}      data-kite-cta-id="product-card"      data-kite-role="primary"      data-kite-event="product_viewed"      data-kite-item={product.id}    >      {/* Image â€” fixed 3:4 proportion, identical across all cards */}      <div className="relative overflow-hidden aspect-[3/4] bg-[#F0EBE4] flex-shrink-0">        <Image          src={displayImage?.src ?? ''}          alt={displayImage?.alt ?? product.name}          fill          className="object-cover object-center transition-transform duration-[800ms] ease-out group-hover:scale-[1.04]"          sizes="(max-width: 640px) 80vw, (max-width: 1024px) 40vw, 25vw"        />        {product.badge && (          <span            className="absolute top-3 right-3 text-[0.6875rem] font-normal tracking-[0.14em] uppercase px-2 py-0.5 bg-[#F8F5F1]/85 text-[#3B3A38]"            style={{ fontFamily: 'var(--font-inter)' }}          >            {product.badge}          </span>        )}                <SpeciesBadge species={product.species} className="absolute bottom-3 left-3" />        <button          onClick={(e) => {            e.preventDefault();            e.stopPropagation();            toggleWishlist({              id: product.id,              name: product.name,              price: displayPrice,              image: displayImage?.src ?? '',            });          }}          className="absolute bottom-3 right-3 bg-white/80 hover:bg-white p-2 rounded-full shadow-sm transition-colors text-[#3B3A38] z-10"          aria-label="Toggle Wishlist"        >          <svg width="18" height="18" viewBox="0 0 24 24" fill={isWishlisted ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />          </svg>        </button>      </div>      {/* Card body â€” grows to fill remaining height, price row pinned to bottom */}      <div className="px-4 pt-4 pb-5 flex flex-col flex-1 gap-1.5">        {/* Meta block â€” name + optional variant label + volume â€” occupies top of body */}        <div className="flex flex-col gap-1.5 flex-1">          {/* Name â€” Cormorant Garamond per approved typography rules */}          <h3            className="text-[1.125rem] text-[#3B3A38] leading-snug line-clamp-2"            style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontWeight: 400 }}          >            {product.name}          </h3>          {/* Single-variant label */}          {singleVariantLabel && (            <p className="text-[0.75rem] font-light text-[#8D9A83]" style={{ fontFamily: 'var(--font-inter)' }}>              {singleVariantLabel}            </p>          )}          {/* Volume â€” Desktop */}          {volume && (            <p className="hidden md:block text-[0.6875rem] font-light text-[#BEB8AF] tracking-[0.04em]" style={{ fontFamily: 'var(--font-inter)' }}>              {volume}            </p>          )}        </div>        {/* â”€â”€ DESKTOP LAYOUT (md:flex) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <div className="hidden md:flex items-center justify-between gap-2 pt-3">          <div className="flex items-baseline gap-2">            <span              className="text-[1.125rem] text-[#3B3A38] leading-none"              style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontWeight: 300 }}            >              {displayPrice}            </span>            {product.standardPrice && (              <span                className="text-[0.875rem] font-light text-[#BEB8AF]/70 line-through leading-none"                style={{ fontFamily: 'var(--font-inter)' }}              >                {product.standardPrice}              </span>            )}          </div>          {/* Add to Cart */}          <button            type="button"            onClick={handleQuickAdd}            aria-label={`Add ${product.name} to cart`}            className="focus:outline-none focus-visible:ring-1 focus-visible:ring-[#8D9A83] flex-shrink-0 inline-flex items-center gap-1.5 border border-[#3B3A38] text-[#3B3A38] px-3 py-1.5 text-[0.6875rem] font-normal tracking-[0.06em] hover:bg-[#3B3A38] hover:text-[#F8F5F1] transition-colors duration-[800ms]"            style={{ fontFamily: 'var(--font-inter)', whiteSpace: 'nowrap' }}          >            {quickAdded ? (              <>                <svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">                  <polyline points="1 6 4.5 9.5 11 2.5"/>                </svg>                Added              </>            ) : (              <>                <BagIconOutline />                Add to Cart              </>            )}          </button>        </div>        {/* â”€â”€ MOBILE LAYOUT (md:hidden) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <div className="flex flex-col gap-2.5 pt-2 md:hidden">          {/* Row 1: Volume on left, Price on right */}          <div className="flex items-baseline justify-between w-full">            <span className="text-[0.6875rem] font-light text-[#BEB8AF] tracking-[0.04em]" style={{ fontFamily: 'var(--font-inter)' }}>              {volume ?? ''}            </span>            <div className="flex items-baseline gap-1.5 ml-auto">              <span                className="text-[1.125rem] text-[#3B3A38] leading-none"                style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontWeight: 300 }}              >                {displayPrice}              </span>              {product.standardPrice && (                <span                  className="text-[0.75rem] font-light text-[#BEB8AF]/70 line-through leading-none"                  style={{ fontFamily: 'var(--font-inter)' }}                >                  {product.standardPrice}                </span>              )}            </div>          </div>          {/* Row 2: Add to Cart button spanning full width from left to right */}          <button            type="button"            onClick={handleQuickAdd}            aria-label={`Add ${product.name} to cart`}            className="w-full focus:outline-none focus-visible:ring-1 focus-visible:ring-[#8D9A83] inline-flex items-center justify-center gap-1.5 border border-[#3B3A38] text-[#3B3A38] px-3 py-2 text-[0.6875rem] font-normal tracking-[0.06em] hover:bg-[#3B3A38] hover:text-[#F8F5F1] active:bg-[#3B3A38] active:text-[#F8F5F1] transition-colors duration-[400ms]"            style={{ fontFamily: 'var(--font-inter)', whiteSpace: 'nowrap' }}          >            {quickAdded ? (              <>                <svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">                  <polyline points="1 6 4.5 9.5 11 2.5"/>                </svg>                Added              </>            ) : (              <>                <BagIconOutline />                Add to Cart              </>            )}          </button>        </div>      </div>    </Link>  );}// â”€â”€â”€ Trust Markers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€const CORE_COMMITMENTS = [  {    id: 'certified-natural',    numberTag: '01 Â· Standard',    title: 'The 99.5% is certified. Not estimated.',    description:      'Most brands that say "natural" use a loosely defined term. Ours is calculated under ISO 16128-2, the international standard for natural origin measurement. Every batch has a number that can be verified.',    imageSrc: '/commitment_certified_natural.webp',    imageAlt: 'Calm golden retriever resting peacefully beside natural botanical extracts',  },  {    id: 'probiotic-preservation',    numberTag: '02 Â· Safety',    title: 'We replaced the preservatives. All of them.',    description:      'Standard pet care uses MIT, MCIT, parabens, or phenoxyethanol. We use a probiotic system â€” Leuconostoc/Radish Root Ferment â€” that does the same job without any of those.',    imageSrc: '/commitment_probiotic_preservation.webp',    imageAlt: 'Caring human hands gently stroking a fluffy cat resting on clean linen',  },  {    id: 'fine-fragrance',    numberTag: '03 Â· Wellness',    title: 'Fine fragrance, not cover-up scent.',    description:      'IFRA-compliant fragrance profiles built from the same raw material vocabulary as premium personal care.',    imageSrc: '/commitment_fine_fragrance.webp',    imageAlt: 'Botanical fine fragrance ingredients beside a happy dog in a quiet garden setting',  },];function CommitmentCardItem({ commitment }: { commitment: typeof CORE_COMMITMENTS[number] }) {  const [isHovered, setIsHovered] = useState(false);  const [isToggled, setIsToggled] = useState(false);  const isOpen = isHovered || isToggled;  return (    <article      className="group relative overflow-hidden rounded-[2px] cursor-pointer min-h-[340px] md:min-h-[400px] flex flex-col justify-end p-6 md:p-8 transition-all duration-700 ease-out border border-[#E9E2D7]/60 hover:border-[#8D9A83]"      onMouseEnter={() => setIsHovered(true)}      onMouseLeave={() => setIsHovered(false)}      onFocus={() => setIsHovered(true)}      onBlur={() => setIsHovered(false)}      onClick={() => setIsToggled(!isToggled)}      tabIndex={0}      role="article"      aria-expanded={isHovered}    >      {/* Background Image Layer */}      <div className="absolute inset-0 pointer-events-none overflow-hidden">        <Image          src={commitment.imageSrc}          alt={commitment.imageAlt}          fill          className="object-cover object-center transition-all duration-700 ease-out"          style={{            transform: isOpen ? 'scale(1.08)' : 'scale(1.0)',            filter: isOpen ? 'saturate(100%) brightness(0.85)' : 'saturate(55%) brightness(0.72)',          }}          sizes="(max-width: 768px) 100vw, 33vw"        />        {/* Soft Editorial Gradient Overlay */}        <div          className="absolute inset-0 transition-opacity duration-700 ease-out"          style={{            background: isOpen              ? 'linear-gradient(to top, rgba(28,26,24,0.94) 0%, rgba(28,26,24,0.55) 55%, rgba(28,26,24,0.2) 100%)'              : 'linear-gradient(to top, rgba(28,26,24,0.84) 0%, rgba(28,26,24,0.40) 65%, rgba(28,26,24,0.15) 100%)',          }}        />      </div>      {/* Content Container */}      <div className="relative z-10 flex flex-col justify-end text-left">        <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#D8CFC4]/70 mb-2">          {commitment.numberTag}        </p>        {/* Heading */}        <h3          className="text-[#F8F5F1] transition-all duration-500 ease-out"          style={{            fontFamily: 'var(--font-cormorant), Georgia, serif',            fontSize: isOpen ? 'clamp(1.35rem, 2vw, 1.65rem)' : 'clamp(1.2rem, 1.75vw, 1.45rem)',            fontWeight: 300,            lineHeight: 1.22,            letterSpacing: '-0.01em',          }}        >          &ldquo;{commitment.title}&rdquo;        </h3>        {/* Expandable Description */}        <div className="absolute right-6 bottom-6 md:hidden text-[#F8F5F1] transition-transform duration-500" style={{ transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M19 9l-7 7-7-7" strokeLinecap="round" strokeLinejoin="round"/></svg>        </div>        <div          className="overflow-hidden transition-all duration-500 ease-out pr-8 md:pr-0"          style={{            maxHeight: isOpen ? '200px' : '0px',            opacity: isOpen ? 1 : 0,            marginTop: isOpen ? '12px' : '0px',          }}        >          <div className="w-8 h-px bg-[#8D9A83]/50 mb-3" />          <p            className="text-[0.8125rem] font-light text-[#D8CFC4] leading-relaxed"            style={{ fontFamily: 'var(--font-inter)' }}          >            {commitment.description}          </p>        </div>      </div>    </article>  );}function TrustMarkersSection() {  return (    <section      className="py-16 md:py-20 bg-[#F8F5F1] border-t border-[#E9E2D7]"      data-kite-surface="home.trust"      data-kite-surface-type="testimonial"    >      <div className="max-w-[1200px] mx-auto px-6 md:px-8">        {/* Heading row */}        <div className="mb-10 md:mb-12">          <h2            className="text-[#3B3A38] mb-3"            style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontSize: 'clamp(2rem, 3.2vw, 2.625rem)', fontWeight: 300, lineHeight: 1.15 }}          >            Thoughtfully Formulated. Transparently Made.          </h2>          <p className="text-[0.8125rem] font-light text-[#8D9A83] leading-relaxed max-w-[520px]">            Because the standards you expect for yourself should never be lower for the ones who trust you most.          </p>        </div>        {/* Markers â€” 2x2 grid on mobile, 4-column equidistant full-width on desktop */}        <div className="grid grid-cols-2 md:grid-cols-4 gap-8 md:gap-12 w-full justify-between items-start">          {TRUST_MARKERS.map((marker) => (            <TrustMarkerItem key={marker.id} marker={marker} />          ))}        </div>        {/* Core commitments interactive cards */}        <div className="mt-14 pt-12 border-t border-[#E9E2D7] grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8">          {CORE_COMMITMENTS.map((commitment) => (            <CommitmentCardItem key={commitment.id} commitment={commitment} />          ))}        </div>      </div>    </section>  );}// â”€â”€â”€ Video placeholder â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€function VideoPlaceholder({ src, alt, className = '' }: { src: string; alt: string; className?: string }) {  return (    <div className={`relative overflow-hidden group ${className}`}>      <Image src={src} alt={alt} fill className="object-cover object-center transition-[transform,filter] duration-[800ms] ease-out [filter:saturate(50%)] group-hover:[filter:saturate(100%)]" sizes="(max-width: 768px) 100vw, 50vw" />      <div className="absolute inset-0 bg-[#3B3A38]/15 group-hover:bg-[#3B3A38]/25 transition-colors duration-[800ms] pointer-events-none" />      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">        <div className="w-14 h-14 rounded-full border border-[#F8F5F1]/60 flex items-center justify-center bg-[#F8F5F1]/20 backdrop-blur-sm group-hover:scale-110 transition-transform duration-[800ms]">          <svg width="16" height="18" viewBox="0 0 16 18" fill="none" aria-hidden="true"><path d="M2 1l12 8-12 8V1z" fill="#F8F5F1" /></svg>        </div>      </div>      <div className="absolute bottom-3 left-3 text-[#F8F5F1]/70 text-[0.625rem] tracking-[0.2em] uppercase font-normal pointer-events-none">Coming soon</div>    </div>  );}function RevealSection({ children, className = '', delay = 0, id, ...rest }: {  children: React.ReactNode; className?: string; delay?: number; id?: string; [key: string]: unknown;}) {  const { ref, visible } = useReveal(0.3);  return (    <section      ref={ref as React.RefObject<HTMLElement>}      id={id}      className={`anim-blur-slide ${visible ? 'in-view' : ''} ${className}`}      style={{ transitionDelay: `${delay}ms` }}      {...(rest as React.HTMLAttributes<HTMLElement>)}    >      {children}    </section>  );}function RetailersSection() {  return (    <RevealSection className="py-16 md:py-20 bg-[#EDE7DF] border-y border-[#D8CFC4]" data-kite-surface="home.retailers" data-kite-surface-type="logos">      <div className="max-w-[1200px] mx-auto px-6 md:px-8 text-center flex flex-col items-center">        <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-4">Where else you can find us</p>        <h2 className="text-[#3B3A38] mb-8 max-w-[540px]" style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontSize: 'clamp(1.75rem, 2.5vw, 2.25rem)', fontWeight: 300, lineHeight: 1.15 }}>          Present at multiple places for your convenience.        </h2>        <div className="flex items-center justify-center gap-10 md:gap-16">          <a href="https://amazon.in" target="_blank" rel="noopener noreferrer" className="opacity-70 hover:opacity-100 saturate-50 hover:saturate-100 transition-all duration-300 w-[100px] md:w-[130px] flex justify-center items-center" aria-label="Amazon">            <img src="/amazon_logo.webp" alt="Amazon" className="w-full object-contain" />          </a>          <a href="https://flipkart.com" target="_blank" rel="noopener noreferrer" className="opacity-70 hover:opacity-100 saturate-50 hover:saturate-100 transition-all duration-300 w-[100px] md:w-[130px] flex justify-center items-center" aria-label="Flipkart">            <img src="/flipkart_logo.webp" alt="Flipkart" className="w-full object-contain" />          </a>        </div>      </div>    </RevealSection>  );}function InstagramSection() {  return (    <RevealSection className="py-16 md:py-24 bg-[#F8F5F1]" data-kite-surface="home.instagram" data-kite-surface-type="community">      <div className="max-w-[1000px] mx-auto px-6 md:px-8">        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-16 items-center">          <div className="flex flex-col items-start max-w-[420px] mx-auto md:mx-0 text-center md:text-left">            <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-4 w-full">Our Community</p>            <h2 className="text-[#3B3A38] mb-5 w-full" style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontSize: 'clamp(2rem, 3.2vw, 2.75rem)', fontWeight: 300, lineHeight: 1.15 }}>              Share your story.            </h2>            <p className="text-[0.9375rem] font-light text-[#68735F] leading-relaxed mb-8">              We are building a community for pets and the people who love them. Join us on Instagram to share your experience and see how Furrytail is making relationships better.            </p>            <div className="w-full flex justify-center md:justify-start">              <a href="https://instagram.com" target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 text-[0.75rem] font-medium tracking-[0.1em] uppercase text-[#F8F5F1] bg-[#3B3A38] px-8 py-3.5 hover:bg-[#68735F] transition-colors duration-300">                Follow Us              </a>            </div>          </div>          <div className="flex justify-center md:justify-end">            <div className="relative w-[260px] h-[540px] rounded-[38px] border-[10px] border-[#3B3A38] shadow-2xl overflow-hidden bg-white transform rotate-0 transition-transform duration-700 ease-out">              <div className="absolute top-0 inset-x-0 h-5 bg-[#3B3A38] rounded-b-[16px] mx-16 z-10" />              <img src="/instagram_screenshot.webp" alt="Furrytail Instagram Community" className="w-full h-full object-cover object-top" />            </div>          </div>        </div>      </div>    </RevealSection>  );}// â”€â”€â”€ Contact form â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€function ContactForm() {  const [status, setStatus] = useState<'idle' | 'sending' | 'success' | 'error'>('idle');  const [form, setForm] = useState({ name: '', email: '', message: '' });  const [errors, setErrors] = useState<Partial<typeof form>>({});  function validate() {    const e: Partial<typeof form> = {};    if (!form.name.trim()) e.name = 'Please enter your name.';    if (!form.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) e.email = 'Please enter a valid email.';    if (!form.message.trim()) e.message = 'Please write a message.';    return e;  }  async function handleSubmit(e: FormEvent<HTMLFormElement>) {    e.preventDefault();    const errs = validate();    setErrors(errs);    if (Object.keys(errs).length > 0) return;    setStatus('sending');    try {      const res = await fetch('/api/v1/kite-platform/website-contact-form-management/submit', {        method: 'POST',        headers: { 'Content-Type': 'application/json' },        body: JSON.stringify({ email: form.email, subject: `Furrytail enquiry from ${form.name}`, text_body: form.message, json_body: { name: form.name, email: form.email, message: form.message } }),      });      if (!res.ok) throw new Error('Request failed');      setStatus('success');      window.__kite && window.__kite.conversion('contact');    } catch { setStatus('error'); }  }  if (status === 'success') {    return (      <div className="flex flex-col gap-3" aria-live="polite">        <div className="flex items-center gap-2">          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="#68735F" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><circle cx="8" cy="8" r="7"/><polyline points="5 8 7 10 11 6"/></svg>          <p className="text-[0.78rem] font-normal text-[#68735F] tracking-wide">Message received.</p>        </div>        <p className="text-[0.78rem] font-light text-[#68735F] leading-relaxed">We will be in touch within a day or two.</p>      </div>    );  }  const fieldClass = (err?: string) => `w-full h-11 px-4 bg-transparent border text-[0.875rem] font-light text-[#3B3A38] placeholder:text-[#BEB8AF] outline-none transition-colors duration-200 focus:border-[#3B3A38] ${err ? 'border-[#c0392b]' : 'border-[#D8CFC4]'}`;  const errIcon = <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true"><circle cx="5" cy="5" r="4.5"/><line x1="5" y1="3" x2="5" y2="5.5"/><circle cx="5" cy="7" r="0.4" fill="currentColor" stroke="none"/></svg>;  return (    <form onSubmit={handleSubmit} noValidate className="flex flex-col gap-4" data-kite-form-type="contact" data-kite-conversion="contact" data-kite-event="contact_completed" data-kite-conversion-hook>      <div className="flex flex-col gap-1.5">        <label htmlFor="contact-name" className="text-[0.625rem] font-normal tracking-[0.15em] uppercase text-[#68735F]">Name</label>        <input id="contact-name" name="name" type="text" autoComplete="name" required value={form.name} onChange={(e) => { setForm((f) => ({ ...f, name: e.target.value })); setErrors((er) => ({ ...er, name: undefined })); }} className={fieldClass(errors.name)} placeholder="Your name" />        {errors.name && <p className="text-[0.65rem] text-[#c0392b] flex items-center gap-1" role="alert">{errIcon}{errors.name}</p>}      </div>      <div className="flex flex-col gap-1.5">        <label htmlFor="contact-email" className="text-[0.625rem] font-normal tracking-[0.15em] uppercase text-[#68735F]">Email</label>        <input id="contact-email" name="email" type="email" autoComplete="email" required value={form.email} onChange={(e) => { setForm((f) => ({ ...f, email: e.target.value })); setErrors((er) => ({ ...er, email: undefined })); }} className={fieldClass(errors.email)} placeholder="you@example.com" />        {errors.email && <p className="text-[0.65rem] text-[#c0392b] flex items-center gap-1" role="alert">{errIcon}{errors.email}</p>}      </div>      <div className="flex flex-col gap-1.5">        <label htmlFor="contact-message" className="text-[0.625rem] font-normal tracking-[0.15em] uppercase text-[#68735F]">Message</label>        <textarea id="contact-message" name="message" rows={4} required value={form.message} onChange={(e) => { setForm((f) => ({ ...f, message: e.target.value })); setErrors((er) => ({ ...er, message: undefined })); }} className={`w-full px-4 py-3 bg-transparent border text-[0.875rem] font-light text-[#3B3A38] placeholder:text-[#BEB8AF] outline-none transition-colors duration-200 focus:border-[#3B3A38] resize-none ${errors.message ? 'border-[#c0392b]' : 'border-[#D8CFC4]'}`} placeholder="Tell us what is on your mind." />        {errors.message && <p className="text-[0.65rem] text-[#c0392b] flex items-center gap-1" role="alert">{errIcon}{errors.message}</p>}      </div>      <div className="flex flex-col gap-2">        <button type="submit" disabled={status === 'sending'} className="hero-btn-primary w-full justify-center" style={{ minHeight: '48px' }} data-kite-cta-id="contact-submit" data-kite-role="primary" data-kite-event="contact_requested">          {status === 'sending' ? 'Sending...' : <><span>Send Message</span><BtnArrow /></>}        </button>        {status === 'error' && <p className="text-[0.65rem] text-[#c0392b] flex items-center gap-1.5" role="alert"><svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true"><circle cx="5" cy="5" r="4.5"/><line x1="3.5" y1="3.5" x2="6.5" y2="6.5"/><line x1="6.5" y1="3.5" x2="3.5" y2="6.5"/></svg>Please try again in a moment.</p>}      </div>    </form>  );}// Maps a pillar id onto its WooCommerce category name.const PILLAR_CATEGORY: Record<string, string> = {  ritual: 'Daily Ritual',  defense: 'Defense',  remedy: 'Remedy',  refresh: 'Refresh',};function MobilePillarItem({ pillar, idx }: { pillar: typeof pillars[number]; idx: number }) {  const { products } = useProducts();  const [isOpen, setIsOpen] = useState(false);  const ref = useRef<HTMLElement>(null);  const num = String(idx + 1).padStart(2, '0');  const handleToggle = () => setIsOpen(!isOpen);  return (    <article      ref={ref as React.RefObject<HTMLElement>}      key={pillar.id}      className="relative overflow-hidden cursor-pointer"      style={{ height: isOpen ? '576px' : '211px', transition: 'height 800ms cubic-bezier(0.4, 0, 0.2, 1)' }}      onClick={handleToggle}      onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') handleToggle(); }}      tabIndex={0}      role="button"      aria-label={`Learn about ${pillar.name}`}      aria-expanded={isOpen}    >      <div className="absolute inset-0 pointer-events-none">        <Image src={pillar.image?.src ?? ''} alt={pillar.image?.alt ?? pillar.name} fill className="object-cover transition-[filter] duration-[800ms] ease-out" style={{ objectPosition: pillar.id === 'defense' ? (isOpen ? 'center 75%' : 'center 30%') : 'center', filter: isOpen ? 'saturate(90%)' : 'saturate(30%)', transform: pillar.id === 'defense' ? 'scale(1.35)' : undefined }} sizes="100vw" />        <div className="absolute inset-0 transition-opacity duration-[800ms]" style={{ background: isOpen ? 'linear-gradient(to top, rgba(30,28,26,0.85) 0%, rgba(30,28,26,0.30) 55%, rgba(30,28,26,0.06) 100%)' : 'linear-gradient(to top, rgba(30,28,26,0.72) 0%, rgba(30,28,26,0.20) 60%, transparent 100%)' }} />      </div>      <div className="relative z-10 flex flex-col justify-end h-full px-5 py-5">        <div className="flex items-center justify-between gap-2 mb-1">          <p className="text-[0.625rem] font-normal tracking-[0.28em] uppercase text-[#D8CFC4]/50">{num}</p>          {pillar.badge && (            <span className="text-[0.5625rem] font-normal tracking-[0.1em] uppercase text-[#F8F5F1]/80 bg-[#3B3A38]/70 px-2 py-0.5 rounded-[2px]" style={{ opacity: isOpen ? 1 : 0, transition: 'opacity 800ms ease-out' }}>              {pillar.badge}            </span>          )}        </div>        <div className="flex items-center justify-between gap-4 w-full">
            <h3 className="text-[#F8F5F1] flex items-baseline gap-2" style={{ fontFamily: 'var(--font-cormorant)', fontSize: '1.5rem', fontWeight: 300, lineHeight: 1.2 }}><span>{pillar.name}</span>{/* @ts-ignore */}{pillar.subheading && <span className="text-[#D8CFC4] italic tracking-wide" style={{ fontSize: '1.125rem' }}>{pillar.subheading}</span>}</h3>
            <div className="text-[#F8F5F1] transition-transform duration-500" style={{ transform: isOpen ? "rotate(180deg)" : "rotate(0deg)" }}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M19 9l-7 7-7-7" strokeLinecap="round" strokeLinejoin="round"/></svg>
            </div>
          </div>        <div className="overflow-hidden pr-6" style={{ maxHeight: isOpen ? '450px' : '0px', opacity: isOpen ? 1 : 0, marginTop: isOpen ? '12px' : '0px', transition: 'max-height 800ms cubic-bezier(0.4, 0, 0.2, 1), opacity 700ms ease-out, margin-top 800ms ease-out' }}>          <div className="w-6 h-px bg-[#F8F5F1]/25 mb-3" />          <p className="text-[#E8E0D6] mb-2" style={{ fontFamily: 'var(--font-cormorant)', fontSize: '1.5rem', fontWeight: 300, lineHeight: 1.2 }}>{pillar.tagline}</p>          <p className="text-[0.875rem] font-light text-[#BEB8AF] leading-relaxed mb-4">{pillar.body}</p>          <div className="flex flex-col gap-2 mb-4">            {products.filter(p => p.category === PILLAR_CATEGORY[pillar.id]).map(p => (              <Link href={`/products/${p.id}`} key={p.id} className="group flex items-center gap-3 bg-[#F8F5F1]/5 hover:bg-[#F8F5F1]/10 p-2 rounded-sm border border-[#F8F5F1]/10 transition-colors" onClick={(e) => e.stopPropagation()}>                <div className="relative w-12 h-12 flex-shrink-0 bg-white/10 rounded-sm overflow-hidden">                  <Image src={p.image.src} alt={p.name} fill className="object-cover group-hover:scale-110 transition-transform duration-500" sizes="48px" />                </div>                <div className="text-left">                  <p className="text-[0.75rem] text-[#F8F5F1] font-medium leading-tight">{p.name}</p>                  <p className="text-[0.65rem] text-[#F8F5F1]/60 mt-0.5">{p.price}</p>                </div>              </Link>            ))}          </div>        </div>      </div>    </article>  );}// â”€â”€â”€ Pillar accordion row â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€function PillarAccordionRow() {  const { products } = useProducts();  const [activeIdx, setActiveIdx] = useState<number | null>(null);  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);  const handleToggle = (idx: number) => { setActiveIdx((prev) => (prev === idx ? null : idx)); };  const effectiveIdx = hoveredIdx !== null ? hoveredIdx : activeIdx;  return (    <>      {/* Desktop */}      <div className="hidden md:flex gap-[2px]" style={{ height: '480px' }} onMouseLeave={() => setHoveredIdx(null)}>        {pillars.map((pillar, idx) => {          const isActive = effectiveIdx === idx;          const hasActive = effectiveIdx !== null;          const num = String(idx + 1).padStart(2, '0');          return (            <article key={pillar.id} className="relative overflow-hidden cursor-pointer" style={{ flex: isActive ? '3.2' : hasActive ? '0.6' : '1', transition: 'flex 800ms cubic-bezier(0.4, 0, 0.2, 1)', minWidth: 0 }} onMouseEnter={() => setHoveredIdx(idx)} onClick={() => handleToggle(idx)} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') handleToggle(idx); }} tabIndex={0} role="button" aria-label={`Learn about ${pillar.name}`} aria-expanded={activeIdx === idx}>              <div className="absolute inset-0 pointer-events-none">                <Image src={pillar.image?.src ?? ''} alt={pillar.image?.alt ?? pillar.name} fill className="object-cover transition-[transform,filter] duration-[800ms] ease-out" style={{ objectPosition: pillar.id === 'defense' ? (isActive ? 'center 75%' : 'center 30%') : 'center', filter: isActive ? 'saturate(90%)' : 'saturate(30%)', transform: pillar.id === 'defense' ? (isActive ? 'scale(1.404)' : 'scale(1.35)') : (isActive ? 'scale(1.04)' : 'scale(1)') }} sizes="(max-width: 768px) 100vw, 40vw" />                <div className="absolute inset-0 transition-opacity duration-[800ms]" style={{ background: isActive ? 'linear-gradient(to top, rgba(30,28,26,0.82) 0%, rgba(30,28,26,0.28) 55%, rgba(30,28,26,0.04) 100%)' : 'linear-gradient(to top, rgba(30,28,26,0.70) 0%, rgba(30,28,26,0.22) 50%, rgba(30,28,26,0.04) 100%)' }} />              </div>              {/* Cards 0+1 expand rightward â†’ content anchored left; cards 2+3 expand leftward â†’ content anchored right */}              <div className={`relative z-10 flex flex-col justify-end h-full px-5 py-6 lg:px-6 lg:py-7 ${idx >= 2 ? 'items-end text-right' : 'items-start text-left'}`}>                <div className={`flex items-center gap-2 mb-1 ${idx >= 2 ? 'flex-row-reverse' : ''}`}>                  <p className="text-[0.625rem] font-normal tracking-[0.28em] uppercase transition-all duration-[800ms]" style={{ color: isActive ? 'rgba(248,245,241,0.6)' : 'rgba(216,207,196,0.5)' }}>{num}</p>                  {pillar.badge && (                    <span className="text-[0.5625rem] font-normal tracking-[0.1em] uppercase text-[#F8F5F1]/80 bg-[#3B3A38]/70 px-2 py-0.5 rounded-[2px]" style={{ opacity: isActive ? 1 : 0, transition: 'opacity 800ms ease-out' }}>                      {pillar.badge}                    </span>                  )}                </div>                <h3 className={`text-[#F8F5F1] mt-2 flex items-baseline gap-3 ${idx >= 2 ? 'flex-row-reverse' : ''}`} style={{ fontFamily: 'var(--font-cormorant)', fontSize: isActive ? '1.75rem' : '1.5rem', fontWeight: 300, letterSpacing: '-0.01em', lineHeight: 1.2, transition: 'font-size 800ms cubic-bezier(0.4, 0, 0.2, 1)' }}><span>{pillar.name}</span>{/* @ts-ignore */}{pillar.subheading && <span className="text-[#BEB8AF] italic tracking-wide whitespace-nowrap" style={{ fontSize: isActive ? '1.25rem' : '1.125rem', transition: 'font-size 800ms cubic-bezier(0.4, 0, 0.2, 1)' }}>{pillar.subheading}</span>}</h3>                <div className="overflow-hidden" style={{ maxHeight: isActive ? '450px' : '0px', opacity: isActive ? 1 : 0, marginTop: isActive ? '14px' : '0px', transition: 'max-height 800ms cubic-bezier(0.4, 0, 0.2, 1), opacity 700ms ease-out, margin-top 800ms ease-out' }}>                  <div className={`w-8 h-px bg-[#F8F5F1]/25 mb-4 ${idx >= 2 ? 'ml-auto' : ''}`} />                  <p className="text-[#E8E0D6] mb-3" style={{ fontFamily: 'var(--font-cormorant)', fontSize: '1.5rem', fontWeight: 300, lineHeight: 1.2 }}>{pillar.tagline}</p>                  <p className="text-[0.875rem] font-light text-[#BEB8AF] leading-relaxed mb-4">{pillar.body}</p>                                    <div className={`flex flex-row flex-wrap gap-2 mb-4 ${idx >= 2 ? 'justify-end' : 'justify-start'}`}>                    {products.filter(p => p.category === PILLAR_CATEGORY[pillar.id]).map(p => (                      <Link href={`/products/${p.id}`} key={p.id} className={`group flex items-center gap-3 bg-[#F8F5F1]/5 hover:bg-[#F8F5F1]/10 p-2 rounded-sm border border-[#F8F5F1]/10 transition-colors w-full max-w-[240px] ${idx >= 2 ? 'flex-row-reverse text-right' : 'text-left'}`} onClick={(e) => e.stopPropagation()}>                        <div className="relative w-12 h-12 flex-shrink-0 bg-white/10 rounded-sm overflow-hidden">                          <Image src={p.image.src} alt={p.name} fill className="object-cover group-hover:scale-110 transition-transform duration-500" sizes="48px" />                        </div>                        <div>                          <p className="text-[0.75rem] text-[#F8F5F1] font-medium leading-tight line-clamp-1">{p.name}</p>                          <p className="text-[0.65rem] text-[#F8F5F1]/60 mt-0.5">{p.price}</p>                        </div>                      </Link>                    ))}                  </div>                </div>              </div>            </article>          );        })}      </div>      {/* Mobile â€” Auto opens on scroll into view */}      <div className="flex flex-col gap-px md:hidden">        {pillars.map((pillar, idx) => (          <MobilePillarItem key={pillar.id} pillar={pillar} idx={idx} />        ))}      </div>    </>  );}// â”€â”€â”€ Our Range Gallery â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€// Five products shown as a curated editorial exhibition.// Desktop: scroll-linked horizontal-motion (vertical scroll drives horizontal pan).// Mobile/reduced-motion: native horizontal swipe row.// Uses the canonical website-scroll-management horizontal-motion contract.function OurRangeGallery() {  const { products } = useProducts();  const sectionRef = useRef<HTMLElement>(null);  const viewportRef = useRef<HTMLDivElement>(null);  const stripRef = useRef<HTMLDivElement>(null);  useEffect(() => {    const root = sectionRef.current;    const viewport = viewportRef.current;    const strip = stripRef.current;    if (!root || !viewport || !strip) return;    // â”€â”€ Ancestor-overflow patch â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€    const patched: { el: HTMLElement; o: string; x: string; y: string }[] = [];    const breaks = (v: string) => v === 'hidden' || v === 'auto' || v === 'scroll';    for (      let el: HTMLElement | null = root;      el && el !== document.documentElement;      el = el.parentElement    ) {      const cs = getComputedStyle(el);      if (!breaks(cs.overflow) && !breaks(cs.overflowX) && !breaks(cs.overflowY)) continue;      const s = el.style;      patched.push({ el, o: s.overflow, x: s.overflowX, y: s.overflowY });      s.overflow = 'clip';    }    // â”€â”€ horizontal-motion init (inlined from canonical init.js) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€    const priorStripWidth = strip.style.width;    strip.style.width = '100%';    const upgradeStrip = () => {      strip.style.overflowX = 'visible';      strip.style.scrollSnapType = 'none';      if (strip.scrollLeft) strip.scrollLeft = 0;    };    const restoreStrip = () => {      strip.style.overflowX = '';      strip.style.scrollSnapType = '';    };    const mq = window.matchMedia('(max-width: 767px)');    const reduceMq = window.matchMedia('(prefers-reduced-motion: reduce)');    const isStatic = () => mq.matches || reduceMq.matches;    let raf = 0;    let inside = false;    let pinRange = 0;    let distance = 0;    const PACE = 1.6;    const layout = () => {      if (isStatic()) {        root.style.height = '';        pinRange = 0;        distance = 0;        strip.style.transform = 'translate3d(0,0,0)';        restoreStrip();        return;      }      upgradeStrip();      distance = Math.max(0, strip.scrollWidth - viewport.clientWidth);      if (distance <= 0) {        root.style.height = '';        pinRange = 0;        strip.style.transform = 'translate3d(0,0,0)';        restoreStrip();        return;      }      pinRange = distance * PACE;      root.style.height = `${pinRange + window.innerHeight}px`;    };    const update = () => {      raf = 0;      if (isStatic() || pinRange <= 0 || distance <= 0) {        strip.style.transform = 'translate3d(0,0,0)';        return;      }      const rect = root.getBoundingClientRect();      const progress = Math.min(1, Math.max(0, -rect.top / pinRange));      strip.style.transform = `translate3d(${-progress * distance}px, 0, 0)`;    };    const schedule = () => {      if (raf) return;      raf = requestAnimationFrame(() => { layout(); update(); });    };    const onScroll = () => {      if (!inside || raf) return;      raf = requestAnimationFrame(update);    };    const gate = new IntersectionObserver(      (entries) => {        inside = entries[0]?.isIntersecting ?? false;        if (inside) schedule();      },      { rootMargin: '0px', threshold: 0 }    );    gate.observe(root);    const resizeObs = new ResizeObserver(schedule);    resizeObs.observe(strip);    mq.addEventListener('change', schedule);    reduceMq.addEventListener('change', schedule);    window.addEventListener('scroll', onScroll, { passive: true });    window.addEventListener('resize', schedule, { passive: true });    strip.querySelectorAll('img').forEach((img) => {      if (!(img as HTMLImageElement).complete) {        img.addEventListener('load', schedule, { once: true });      }    });    schedule();    return () => {      patched.forEach(({ el, o, x, y }) => {        el.style.overflow = o;        el.style.overflowX = x;        el.style.overflowY = y;      });      gate.disconnect();      resizeObs.disconnect();      mq.removeEventListener('change', schedule);      reduceMq.removeEventListener('change', schedule);      window.removeEventListener('scroll', onScroll);      window.removeEventListener('resize', schedule);      if (raf) cancelAnimationFrame(raf);      root.style.height = '';      strip.style.transform = '';      strip.style.width = priorStripWidth;      restoreStrip();    };  }, []);  return (    // overflow-clip on the section root â€” never overflow-hidden (breaks sticky pin)    <section      ref={sectionRef}      className="overflow-clip max-md:!h-auto border-t border-[#E9E2D7]"      data-website-scroll-management      data-scroll-pattern="horizontal-motion"      data-kite-surface="home.our-range"      data-kite-surface-type="features"      id="all-products"    >      {/* Sticky viewport â€” h-screen, flex-col: header + products; max-md fallback: static */}      <div        ref={viewportRef}        className="sticky top-0 h-screen flex flex-col justify-center max-md:static max-md:h-auto"        data-scroll-viewport      >        {/* Section header â€” pinned inside the viewport alongside the products */}        <div className="max-w-[1200px] mx-auto w-full px-6 md:px-8 pt-12 md:pt-16 pb-8 md:pb-10 flex flex-col sm:flex-row sm:items-end justify-between gap-4 flex-shrink-0">          <div>            <p              className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#BEB8AF] mb-3"              style={{ fontFamily: 'var(--font-inter)' }}            >              {ourRange.eyebrow}            </p>            <h2              className="text-[#3B3A38] leading-tight"              style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontSize: 'clamp(2rem, 3.2vw, 2.625rem)', fontWeight: 300, lineHeight: 1.15 }}            >              {ourRange.heading}            </h2>          </div>          <SecondaryOutlineBtn            href="/shop"            data-kite-cta-id="our-range-shop-cta"            data-kite-role="secondary"            data-kite-event="shop_clicked"          >            Shop Collection          </SecondaryOutlineBtn>        </div>        {/* Strip â€” authored as native swipe row; JS upgrades to translate on desktop */}        <div          ref={stripRef}          className="w-full flex items-center gap-10 md:gap-14 overflow-x-auto snap-x px-6 md:px-16 pb-16 md:pb-10 will-change-transform"          style={{ scrollbarWidth: 'none' } as React.CSSProperties}          data-scroll-strip        >          {products.map((product, i) => (            <Link              key={product.id}              href={`/products/${product.id}`}              className="group flex-[0_0_72%] md:flex-[0_0_26%] min-w-0 snap-center flex flex-col items-center gap-6 focus:outline-none focus-visible:ring-1 focus-visible:ring-[#8D9A83] cursor-pointer"              data-kite-cta-id="our-range-product"              data-kite-role="primary"              data-kite-event="product_viewed"              data-kite-item={product.id}            >              {/* Circle image */}              <div                className="relative overflow-hidden rounded-full border border-[#D8CFC4] flex-shrink-0"                style={{                  width: 'clamp(200px, 22vw, 280px)',                  height: 'clamp(200px, 22vw, 280px)',                  transition: 'border-color 800ms ease-out, box-shadow 800ms ease-out',                }}                onMouseEnter={(e) => {                  (e.currentTarget as HTMLDivElement).style.borderColor = '#8D9A83';                  (e.currentTarget as HTMLDivElement).style.boxShadow = '0 8px 32px rgba(59,58,56,0.10)';                }}                onMouseLeave={(e) => {                  (e.currentTarget as HTMLDivElement).style.borderColor = '#D8CFC4';                  (e.currentTarget as HTMLDivElement).style.boxShadow = 'none';                }}              >                <img                  src={product.image?.src ?? ''}                  alt={product.image?.alt ?? product.name}                  loading="eager"                  className="absolute inset-0 w-full h-full object-cover object-center"                  style={{ transition: 'transform 900ms ease-out' }}                  onMouseEnter={(e) => { (e.currentTarget as HTMLImageElement).style.transform = 'scale(1.04) rotate(-30deg)'; }}                  onMouseLeave={(e) => { (e.currentTarget as HTMLImageElement).style.transform = 'scale(1) rotate(0deg)'; }}                />                {/* Soft editorial vignette */}                <div                  className="absolute inset-0 rounded-full pointer-events-none"                  style={{ background: 'radial-gradient(ellipse at center, transparent 55%, rgba(59,58,56,0.12) 100%)' }}                  aria-hidden="true"                />              </div>              {/* Text â€” name + descriptor only, no price/badge/button */}              <div className="flex flex-col items-center gap-2 text-center max-w-[220px]">                <h3                  className="text-[#3B3A38]"                  style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontSize: 'clamp(1.25rem, 1.8vw, 1.5rem)', fontWeight: 300, lineHeight: 1.15, letterSpacing: '-0.01em' }}                >                  {product.name}                </h3>                <p                  className="text-[0.75rem] font-light text-[#8D9A83] leading-[1.55]"                  style={{ fontFamily: 'var(--font-inter)' }}                >                  {product.descriptor}                </p>              </div>            </Link>          ))}          {/* Trailing breathing room */}          <div className="flex-shrink-0 w-6 md:w-16" aria-hidden="true" />        </div>      </div>    </section>  );}// NatureFormulaSection has been replaced by the FeaturedIngredients component// imported from @/components/FeaturedIngredients// â”€â”€â”€ Main page â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€export default function Home() {  const heroRef = useRef<HTMLElement>(null);  const [heroVisible, setHeroVisible] = useState(false);  // "Where most people begin" shows a subset of the range as an introduction.  const { products } = useProducts();  const bestSellersGrid = products.slice(0, 8);  useEffect(() => {    const t = setTimeout(() => setHeroVisible(true), 100);    return () => clearTimeout(t);  }, []);  return (    <ClientProviders>    <div className="min-h-screen bg-[#F8F5F1]" style={{ overflow: 'clip' }}>      <Navbar />      <main className="bg-[#F8F5F1]" data-kite-page-id="home" data-kite-page-type="landing">        {/* â”€â”€ 1. HERO â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <section          ref={heroRef as React.RefObject<HTMLElement>}          className="hero hero-fullbleed"          data-kite-surface="home.hero"          data-kite-surface-type="hero"        >          {/* Mobile Video (Cropped) */}          <video            autoPlay            loop            muted            playsInline            className="absolute inset-0 w-full h-full object-cover object-center block md:hidden"          >            <source src="/mobile_hero.webm" type="video/webm" />
            <source src="/mobile_hero_opt.mp4" type="video/mp4" />                    </video>            {/* Mobile Overlay: bottom-to-top gradient up to 40% height for text legibility */}          <div            aria-hidden="true"            className="block md:hidden"            style={{              position: 'absolute',              inset: 0,              background: 'linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0) 100%)',              pointerEvents: 'none',            }}          />          {/* Desktop Video */}          <video            autoPlay            loop            muted            playsInline            className="absolute inset-0 w-full h-full object-cover object-right hidden md:block"          >            <source src="/desktop_hero.webm" type="video/webm" />
            <source src="/desktop_hero_opt.mp4" type="video/mp4" />          </video>          {/* Desktop Overlay: bottom-left quadrant radial gradient for text legibility */}          <div            aria-hidden="true"            className="hidden md:block"            style={{              position: 'absolute',              inset: 0,              background: 'linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0) 100%)',              pointerEvents: 'none',            }}          />          {/* Copy â€” left-aligned */}          <div className={`hero-copy hero-copy-left transition-[opacity,transform] duration-700 ease-out ${heroVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-[14px]'}`}>            <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#D8CFC4]/70 mb-[8px]">{hero.eyebrow}</p>            <h1 className="text-[#F8F5F1] text-[clamp(2.25rem,4.2vw,3.75rem)] font-light leading-[1.1] tracking-[-0.015em] mb-[8px]" style={{ fontFamily: 'var(--font-cormorant), Georgia, serif' }}>              {hero.headline}            </h1>            <p className="intro text-[0.75rem] md:text-[0.8125rem] font-light text-[#D8CFC4] tracking-[0.02em] leading-relaxed mb-[16px] max-w-[520px]" style={{ fontFamily: 'var(--font-inter)', marginTop: '8px' }}>              {hero.subline}            </p>            <div className="hero-actions hero-actions-left mt-[16px]">              <Link href={hero.primaryHref || '/shop'} className="hero-btn-primary hero-btn-white" data-kite-cta-id="hero-shop-now" data-kite-role="primary" data-kite-event="shop_clicked">                {hero.primaryCta}<BtnArrow />              </Link>            </div>          </div>        </section>        {/* â”€â”€ 2. FOUR PILLARS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <section id="pillars" className="py-16 md:py-20 bg-[#F8F5F1]" data-kite-surface="home.pillars" data-kite-surface-type="features">          <div className="max-w-[1200px] mx-auto px-6 md:px-8">            <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-8">              <div>                <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-2">A Ritual Of Four Categories</p>                <h2 className="text-[#3B3A38]" style={{ fontFamily: 'var(--font-cormorant)', fontSize: 'clamp(2rem, 3.2vw, 2.625rem)', fontWeight: 300, lineHeight: 1.15 }}>Every Ritual Has A Purpose.</h2>              </div>              <SecondaryOutlineBtn                href="/shop"                className="hidden sm:inline-flex"                data-kite-cta-id="pillars-explore-all"                data-kite-role="secondary"                data-kite-event="range_explored"              >                Shop Collection              </SecondaryOutlineBtn>            </div>            <PillarAccordionRow />            <div className="sm:hidden mt-8 flex justify-center">              <SecondaryOutlineBtn                href="/shop"                data-kite-cta-id="pillars-explore-all-mobile"                data-kite-role="secondary"                data-kite-event="range_explored"              >                Shop Collection              </SecondaryOutlineBtn>            </div>          </div>        </section>        {/* â”€â”€ 3. TRUST MARKERS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <TrustMarkersSection />        {/* â”€â”€ 4. FEATURED PRODUCTS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <RevealSection id="best-sellers" className="group py-16 md:py-20 bg-[#EDE7DF]" data-kite-surface="home.best-sellers" data-kite-surface-type="features">          <div className="max-w-[1200px] mx-auto px-6 md:px-8">            <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-10">              <div>                <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-2">{bestSellers.eyebrow}</p>                <h2 className="text-[#3B3A38]" style={{ fontFamily: 'var(--font-cormorant)', fontSize: 'clamp(2rem, 3.2vw, 2.625rem)', fontWeight: 300, lineHeight: 1.15 }}>{bestSellers.heading}</h2>              </div>              <SecondaryOutlineBtn                href="/shop"                className="hidden sm:inline-flex"                data-kite-cta-id="bestsellers-view-all"                data-kite-role="secondary"                data-kite-event="range_explored"              >                Shop Collection              </SecondaryOutlineBtn>            </div>            <div className="flex overflow-x-auto snap-x snap-mandatory gap-4 md:gap-5 pb-8 -mx-6 px-6 md:mx-0 md:px-0 [&::-webkit-scrollbar]:hidden" style={{ scrollPaddingLeft: "1.5rem", scrollbarWidth: "none", msOverflowStyle: "none" }}>
                {bestSellersGrid.map((product, i) => (
                  <div key={product.id} className="flex-shrink-0 w-[80vw] sm:w-[45vw] md:w-[30vw] lg:w-[calc(25%-0.9375rem)] snap-start opacity-0 translate-y-8 group-[.in-view]:opacity-100 group-[.in-view]:translate-y-0 transition-all ease-out" style={{ transitionDuration: "800ms", transitionDelay: `${i * 100}ms` }}>
                    <ProductCard product={product} />
                  </div>
                ))}
              </div>            <div className="sm:hidden mt-10 flex justify-center">              <SecondaryOutlineBtn                href="/shop"                data-kite-cta-id="bestsellers-view-all-mobile"                data-kite-role="secondary"                data-kite-event="range_explored"              >                Shop Collection              </SecondaryOutlineBtn>            </div>          </div>        </RevealSection>        {/* â”€â”€ 5. BRAND PHILOSOPHY â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <section id="brand-philosophy" className="relative bg-[#F8F5F1] overflow-hidden" data-kite-surface="home.brand-philosophy" data-kite-surface-type="features">          <div className="w-full">            <div className="grid grid-cols-1 md:grid-cols-2 gap-0 items-stretch min-h-screen">                            {/* Media col - 50% left, no margin, 100vh height */}              <div className="relative h-[60vh] md:h-screen w-full">                <RevealSection className="w-full h-full">                  <div className="relative w-full h-full overflow-hidden group">                    <Image                      src={brandPhilosophy.image.src}                      alt={brandPhilosophy.image.alt}                      fill                      className="object-cover object-center transition-all duration-[1200ms] ease-out hover:scale-[1.015] saturate-[50%] hover:saturate-[100%] sepia-[20%] hover:sepia-0"                      sizes="(max-width: 768px) 100vw, 50vw"                      priority                    />                  </div>                </RevealSection>              </div>              {/* Copy col - Aligned to design system padding and gaps */}              <div className="relative h-full flex flex-col justify-center px-6 md:px-12 lg:px-16 py-12 md:py-16 bg-[#F0EBE4]">                <RevealSection delay={200}>                  <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-3 md:mb-4">{brandPhilosophy.eyebrow}</p>                  <h2 className="text-[#3B3A38] mb-4 md:mb-6" style={{ fontFamily: 'var(--font-cormorant), Georgia, serif', fontSize: 'clamp(2rem, 3.2vw, 2.75rem)', fontWeight: 300, lineHeight: 1.15, letterSpacing: '-0.01em' }}>                    {brandPhilosophy.heading}                  </h2>                  <div className="flex flex-col gap-4 md:gap-5">                    {brandPhilosophy.body.map((line, i) => (                      <p key={i} className="text-[1rem] md:text-[1.0625rem] font-light text-[#3B3A38]/90 leading-[1.65] max-w-[520px]" style={{ fontFamily: 'var(--font-inter)' }}>                        {line}                      </p>                    ))}                    {brandPhilosophy.cta && (                      <div className="mt-2 md:mt-3">                        <Link href={brandPhilosophy.href || '/about'} className="inline-block text-[0.6875rem] font-normal tracking-[0.2em] uppercase text-[#3B3A38] border-b border-[#3B3A38]/30 hover:border-[#3B3A38] hover:text-[#68735F] transition-all duration-300 pb-1" data-kite-cta-id="brand-story-cta" data-kite-role="secondary" data-kite-event="about_clicked">                          {brandPhilosophy.cta}                        </Link>                      </div>                    )}                  </div>                </RevealSection>              </div>            </div>          </div>        </section>        {/* â”€â”€ 6. OUR RANGE EXHIBITION GALLERY â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <OurRangeGallery />        {/* â”€â”€ 7. FEATURED INGREDIENTS â€” scroll-pinned split editorial â”€â”€â”€â”€â”€â”€â”€â”€ */}        <FeaturedIngredients stories={stories.stories.slice(0, 4)} />        {/* â”€â”€ 7.1 RETAILERS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <RetailersSection />        {/* â”€â”€ 7.2 INSTAGRAM COMMUNITY â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <InstagramSection />        {/* â”€â”€ 8. FOUNDER NOTE â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <RevealSection id="founder-note" className="py-16 md:py-20 bg-[#3B3A38]" data-kite-surface="home.founder-note" data-kite-surface-type="testimonial">          <div className="max-w-[760px] mx-auto px-6 md:px-8 text-center">            <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-8">{founderNote.eyebrow}</p>            <div className="flex justify-center mb-6" aria-hidden="true">              <svg width="28" height="22" viewBox="0 0 28 22" fill="none"><path d="M0 22V12.6C0 5.8 4.2 1.6 12.6 0l1.4 2.4C8.8 3.4 6 6 5.4 10H11V22H0ZM17 22V12.6C17 5.8 21.2 1.6 29.6 0L31 2.4C25.8 3.4 23 6 22.4 10H28V22H17Z" fill="#68735F" opacity="0.6"/></svg>            </div>            <blockquote>              <p className="text-[#F8F5F1] mb-6 italic" style={{ fontFamily: 'var(--font-cormorant)', fontSize: 'clamp(1.5rem, 2.5vw, 1.75rem)', fontWeight: 300, lineHeight: 1.2 }}>{founderNote.pullQuote}</p>            </blockquote>            <div className="w-8 h-px bg-[#68735F] mx-auto mb-6" />            <p className="text-[0.875rem] font-light text-[#D8CFC4] leading-[1.6] mb-5">{founderNote.body}</p>          </div>        </RevealSection>        {/* â”€â”€ 9. CONTACT â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}        <RevealSection id="contact" className="py-16 md:py-20" data-kite-surface="home.contact" data-kite-surface-type="contact">          <div className="max-w-[1200px] mx-auto px-6 md:px-8">            <div className="grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-16 items-stretch">              <div className="relative overflow-hidden group aspect-[4/3] md:aspect-auto md:min-h-[400px]">                <Image src={contact.image.src} alt={contact.image.alt} fill className="object-cover object-center transition-[filter] duration-[800ms] ease-out [filter:saturate(50%)] group-hover:[filter:saturate(100%)]" sizes="(max-width: 768px) 100vw, 50vw" />                <div className="absolute inset-0 bg-[#F8F5F1]/10 pointer-events-none" />              </div>              <div className="flex flex-col gap-6">                <div>                  <p className="text-[0.625rem] font-normal tracking-[0.25em] uppercase text-[#8D9A83] mb-2">{contact.eyebrow}</p>                  <h2 className="text-[#3B3A38] mb-3" style={{ fontFamily: 'var(--font-cormorant)', fontSize: 'clamp(2rem, 3.2vw, 2.625rem)', fontWeight: 300, lineHeight: 1.15 }}>{contact.heading}</h2>                  <p className="text-[0.875rem] font-light text-[#68735F] leading-[1.6]">{contact.body}</p>
                  <div className="mt-4 flex items-center gap-2">
                    <svg className="w-4 h-4 fill-[#8D9A83]" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.888-.788-1.489-1.761-1.663-2.06-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51a5.22 5.22 0 0 0-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 0 1-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 0 1-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.82 9.82 0 0 1 2.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0 0 12.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 0 0 5.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 0 0-3.48-8.413Z"/></svg>
                    <a href="https://wa.me/918796786531" target="_blank" rel="noopener noreferrer" className="text-[0.875rem] font-medium text-[#3B3A38] hover:text-[#8D9A83] transition-colors">WhatsApp: +91 87967 86531</a>
                  </div>                </div>                <ContactForm />              </div>            </div>          </div>        </RevealSection>      </main>      <Footer />    </div>    </ClientProviders>  );}














